script:
(function () {
  'use strict';
  // How important is Social Security? Projects retirement savings to retirement, then draws the
  // income you need from them twice: once with your Social Security benefit (entered by you) and
  // once without it.
  // Saving years k = 1 .. n (n = retirement age - current age): pay_k = income x (1 + raise)^(k-1);
  //   balance = balance x (1 + return before) + pay_k x saving rate (saved at the end of each year).
  // Income needed in retirement year 1 = target % x income at retirement, income x (1 + raise)^n;
  //   it rises with inflation each year after. Social Security in year 1 = monthly benefit (today's
  //   dollars) x 12 x (1 + inflation)^n, then rises with inflation (cost-of-living adjustments).
  // Each retirement year the withdrawal max(0, need - Social Security) is taken at the start of the
  //   year and the rest earns the return during retirement. Savings run out in the first year the
  //   balance cannot cover the withdrawal.
  // Nest egg needed = present value at retirement of the withdrawals (start-of-year, discounted at
  //   the return during retirement). Extra saving rate without Social Security = shortfall /
  //   future value of saving 1% of pay each year until retirement.
  // Verified (Node, scratchpad slc5/hs.test.js): 0% raise, 0% return, $50,000 pay, 10% saved for
  //   20 years from $0 -> $100,000; withdrawals of $40,000 a year with no growth last 2.5 years ->
  //   money runs out in year 3; nest egg for a $30,000 need growing 3% for 25 years at 5% equals the
  //   growing-annuity-due closed form 30,000 x (1 - q^25) / (1 - q), q = 1.03 / 1.05 -> $601,179.98;
  //   a benefit equal to the need -> withdrawals 0, Social Security share 100%; the future value of
  //   1% of pay matches sum 0.01 pay_k (1 + r)^(n-k).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function accumulate(p) {
    var n = p.retireAge - p.age, bal = p.savings, unit = 0;
    for (var k = 1; k <= n; k++) {
      var pay = p.income * Math.pow(1 + p.raise, k - 1);
      bal = bal * (1 + p.preReturn) + pay * p.saveRate;
      unit = unit * (1 + p.preReturn) + pay * 0.01;
    }
    return { balance: bal, incomeAtRetirement: p.income * Math.pow(1 + p.raise, n), fvOnePercent: unit };
  }

  // Draws need - ss (ss = 0 for the "without" case) from the balance each year.
  function drawdown(start, need1, ss1, years, inflation, ret) {
    var bal = start, runOut = 0, pv = 0, rows = [];
    for (var j = 1; j <= years; j++) {
      var g = Math.pow(1 + inflation, j - 1), need = need1 * g, ss = ss1 * g;
      var w = Math.max(0, need - ss);
      pv += w / Math.pow(1 + ret, j - 1);
      if (!runOut && bal < w - 0.005) runOut = j;
      bal = Math.max(0, bal - w) * (1 + ret);
      rows.push({ year: j, need: need, ss: ss, withdrawal: w, balance: bal });
    }
    return { runOut: runOut, end: bal, pvNeeded: pv, rows: rows };
  }

  function clearBody(id) {
    var body = el(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function lasts(d, p) {
    return d.runOut ? 'Runs out at age ' + (p.retireAge + d.runOut - 1) : 'Lasts past age ' + p.planAge;
  }

  function update() {
    var p = { age: read('hsAge'), retireAge: read('hsRetire'), planAge: read('hsPlanAge'), income: read('hsIncome', true),
              raise: read('hsRaise'), saveRate: read('hsSaveRate', true), savings: read('hsSavings', true),
              target: read('hsTarget'), ss: read('hsBenefit', true), preReturn: read('hsPreReturn'),
              postReturn: read('hsPostReturn'), inflation: read('hsInflation') };
    var msg = '';
    if (Object.keys(p).some(function (k) { return isNaN(p[k]); })) msg = 'Fill in every field.';
    else if (p.income < 0 || p.savings < 0 || p.ss < 0) msg = 'Amounts cannot be negative.';
    else if (p.age < 18 || p.age > 90 || p.retireAge < p.age || p.retireAge > 90)
      msg = 'Enter a current age from 18 to 90 and a retirement age no earlier than your current age (up to 90).';
    else if (p.planAge <= p.retireAge || p.planAge > 115) msg = 'The plan must end after you retire (up to age 115).';
    else if (p.saveRate < 0 || p.saveRate > 100 || p.target < 0 || p.target > 200) msg = 'Enter a saving rate from 0% to 100% and an income target from 0% to 200%.';
    else if ([p.raise, p.preReturn, p.postReturn, p.inflation].some(function (r) { return r < -10 || r > 20; }))
      msg = 'Enter raises, returns and inflation from -10% to 20%.';
    else if (p.income === 0 && p.target > 0) msg = 'Enter your household income so the income target can be worked out.';
    var error = el('hsError');
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    p.age = Math.floor(p.age); p.retireAge = Math.floor(p.retireAge); p.planAge = Math.floor(p.planAge);
    ['raise', 'saveRate', 'target', 'preReturn', 'postReturn', 'inflation'].forEach(function (k) { p[k] /= 100; });

    var acc = accumulate(p), n = p.retireAge - p.age, m = p.planAge - p.retireAge;
    var need1 = p.target * acc.incomeAtRetirement, ss1 = p.ss * 12 * Math.pow(1 + p.inflation, n);
    var withSs = drawdown(acc.balance, need1, ss1, m, p.inflation, p.postReturn);
    var without = drawdown(acc.balance, need1, 0, m, p.inflation, p.postReturn);
    var share = need1 > 0 ? Math.min(1, ss1 / need1) : 0;
    var gapWith = Math.max(0, withSs.pvNeeded - acc.balance), gapWithout = Math.max(0, without.pvNeeded - acc.balance);

    setText('hsShare', need1 > 0 ? Math.round(share * 100) + '%' : '–');
    setText('hsShareNote', need1 > 0 ? money.format(ss1 / 12) + ' a month of ' + money.format(need1 / 12) + ' needed in year one' : 'No income target set.');
    setText('hsLastsWith', lasts(withSs, p));
    setText('hsLastsWithout', lasts(without, p));
    setText('hsReplace', money.format(without.pvNeeded - withSs.pvNeeded));
    setText('hsBalance', money.format(acc.balance));
    setText('hsNeed1', money.format(need1));
    setText('hsSs1', money.format(ss1));
    setText('hsEggWith', money.format(withSs.pvNeeded));
    setText('hsEggWithout', money.format(without.pvNeeded));
    function extra(gap) {
      if (gap <= 0) return 'None – on track';
      if (n === 0 || acc.fvOnePercent <= 0) return money.format(gap) + ' more needed now';
      return '+' + (gap / acc.fvOnePercent).toFixed(1) + '% of pay';
    }
    setText('hsExtraWith', extra(gapWith));
    setText('hsExtraWithout', extra(gapWithout));

    var body = clearBody('hsTable');
    for (var j = 0; j < m; j++) {
      var a = withSs.rows[j], b = without.rows[j];
      addRow(body, [String(p.retireAge + j), money.format(a.need), money.format(a.ss), money.format(a.withdrawal),
                    money.format(a.balance), money.format(b.balance)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('hsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
